#!/usr/bin/env python3
"""Exercise the real proxy with configs generated by fast-s5 (loopback only)."""
import argparse
import contextlib
import http.server
import os
from pathlib import Path
import shlex
import socket
import struct
import subprocess
import tempfile
import threading
import time


def free_port():
    with socket.socket() as sock:
        sock.bind(("127.0.0.1", 0))
        return sock.getsockname()[1]


def receive(sock, count):
    data = b""
    while len(data) < count:
        chunk = sock.recv(count - len(data))
        if not chunk:
            raise ConnectionError("Proxy closed the connection")
        data += chunk
    return data


class Handler(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        self.send_response(200)
        self.end_headers()
        self.wfile.write(b"fast-s5 integration ok")

    def log_message(self, *_args):
        pass


def request(port, target, username=None, password="Password01", command=1):
    with socket.create_connection(("127.0.0.1", port), timeout=4) as sock:
        sock.settimeout(4)
        sock.sendall(b"\x05\x01" + (b"\x02" if username else b"\x00"))
        method = receive(sock, 2)
        if username is None:
            assert method == b"\x05\xff", "Anonymous access accepted"
            return False
        assert method == b"\x05\x02", "Password authentication unavailable"
        user, secret = username.encode(), password.encode()
        sock.sendall(b"\x01" + bytes([len(user)]) + user + bytes([len(secret)]) + secret)
        if receive(sock, 2) != b"\x01\x00":
            return False
        sock.sendall(b"\x05" + bytes([command]) + b"\x00\x01\x7f\x00\x00\x01" + struct.pack("!H", target))
        try:
            response = receive(sock, 4)
        except ConnectionError:
            return False
        if response[1] != 0:
            return False
        assert command == 1, "BIND or UDP unexpectedly allowed"
        if response[3] == 1:
            receive(sock, 6)
        elif response[3] == 4:
            receive(sock, 18)
        else:
            receive(sock, receive(sock, 1)[0] + 2)
        sock.sendall(b"GET / HTTP/1.0\r\nHost: localhost\r\n\r\n")
        payload = b""
        while True:
            part = sock.recv(4096)
            if not part:
                break
            payload += part
        return b"fast-s5 integration ok" in payload


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("proxy", type=Path, help="3proxy 0.9.5 executable")
    parser.add_argument("--shell", default="sh")
    args = parser.parse_args()
    executable = str(args.proxy.resolve())
    source = Path(__file__).resolve().parents[1] / "fast-s5.sh"
    with tempfile.TemporaryDirectory(prefix="fast-s5-protocol-") as directory:
        root = Path(directory)
        library = root / "library.sh"
        library.write_text(source.read_text(encoding="utf-8").replace('main "$@"\n', ""), encoding="utf-8", newline="\n")
        port_a, port_b = free_port(), free_port()
        while port_b == port_a:
            port_b = free_port()
        records = {"default": ("alice", port_a), "0123456789": ("bob", port_a), "abcdef0123": ("carol", port_b)}
        for key, (name, port) in records.items():
            path = root / ("account" if key == "default" else f"account.user-{key}")
            path.write_text(f'SOCKS_PORT="{port}"\nSOCKS_USER="{name}"\nSOCKS_PASS="Password01"\n', encoding="utf-8", newline="\n")

        def generate():
            q = lambda path: shlex.quote(path.as_posix())
            script = f'. {q(library)}\nCONF={q(root / "account")}\nRUNTIME={q(root / "proxy.cfg")}\ninit_account_paths\nsecure_runtime() {{ chmod 600 "$1"; }}\nwrite_runtime\n'
            subprocess.run([args.shell, "-c", script], check=True, capture_output=True, text=True)
            config = root / "proxy.cfg"
            config.write_text(config.read_text(encoding="utf-8").replace("-i0.0.0.0", "-i127.0.0.1"), encoding="utf-8", newline="\n")
            return config

        @contextlib.contextmanager
        def running():
            config = generate()
            with (root / "proxy.log").open("ab") as log:
                process = subprocess.Popen([executable, str(config)], stdout=log, stderr=log,
                                           creationflags=subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0)
                try:
                    for _ in range(100):
                        if process.poll() is not None:
                            raise RuntimeError("3proxy exited before it was ready; inspect config compatibility")
                        try:
                            with socket.create_connection(("127.0.0.1", port_b), timeout=.1):
                                break
                        except OSError:
                            time.sleep(.05)
                    else:
                        raise RuntimeError("3proxy did not start listening")
                    yield
                finally:
                    process.terminate()
                    try:
                        process.wait(timeout=5)
                    except subprocess.TimeoutExpired:
                        process.kill()
                        process.wait()

        server = http.server.ThreadingHTTPServer(("127.0.0.1", 0), Handler)
        thread = threading.Thread(target=server.serve_forever, daemon=True)
        thread.start()
        try:
            target = server.server_port
            with running():
                assert request(port_a, target, "alice"), "First shared-port user failed"
                assert request(port_a, target, "bob"), "Second shared-port user failed"
                assert request(port_b, target, "carol"), "Separate-port user failed"
                assert not request(port_a, target), "Anonymous access accepted"
                assert not request(port_a, target, "alice", "WrongPass1"), "Wrong password accepted"
                assert not request(port_a, target, "carol"), "User accepted on wrong port"
                assert not request(port_b, target, "alice"), "User accepted on wrong port"
                assert not request(port_a, target, "alice", command=2), "BIND accepted"
                assert not request(port_a, target, "alice", command=3), "UDP accepted"
            (root / "account").unlink()
            with running():
                assert not request(port_a, target, "alice"), "Deleted user still accepted"
                assert request(port_a, target, "bob"), "Remaining shared-port user failed"
            (root / "account.user-0123456789").unlink()
            with running():
                assert request(port_b, target, "carol"), "Other port affected by deletion"
                try:
                    with socket.create_connection(("127.0.0.1", port_a), timeout=.5):
                        raise AssertionError("Empty port still listening")
                except (ConnectionRefusedError, socket.timeout):
                    pass
        finally:
            server.shutdown()
            server.server_close()
        print("PASS: real 3proxy shared-port authentication, port isolation, deletion, CONNECT-only access")


if __name__ == "__main__":
    main()
